 "content": "from collections import Counter, deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen, comps = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            seen.add((r, c))
            q = deque([(r, c)])
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            comps.append((color, cells))
    return bg, comps


def _canonical(cells):
    variants = []
    for sy in (1, -1):
        for sx in (1, -1):
            for swap in (False, True):
                points = [(y * sy, x * sx) for y, x in cells]
                if swap:
                    points = [(x, y) for y, x in points]
                my = min(y for y, x in points)
                mx = min(x for y, x in points)
                variants.append(tuple(sorted((y - my, x - mx) for y, x in points)))
    return min(variants)


def _corner_l(comp):
    """Return the bounding box and corner of an L with two full edge arms."""
    cells = comp
    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)
    if r1 - r0 + 1 < 4 or c1 - c0 + 1 < 4:
        return None
    area = (r1 - r0 + 1) * (c1 - c0 + 1)
    if len(cells) / area > 0.65:
        return None
    for corner, row, col in (
        ('tl', r0, c0), ('tr', r0, c1),
        ('bl', r1, c0), ('br', r1, c1),
    ):
        if all((row, c) in cells for c in range(c0, c1 + 1)) and all(
                (r, col) in cells for r in range(r0, r1 + 1)):
            return r0, r1, c0, c1, corner
    return None


def _inside_cavity(cells, box):
    r0, r1, c0, c1, corner = box
    if corner == 'tl':
        bounds = (r0 + 1, r1, c0 + 1, c1)
    elif corner == 'tr':
        bounds = (r0 + 1, r1, c0, c1 - 1)
    elif corner == 'bl':
        bounds = (r0, r1 - 1, c0 + 1, c1)
    else:
        bounds = (r0, r1 - 1, c0, c1 - 1)
    a, b, x, y = bounds
    return bool(cells) and all(a <= r <= b and x <= c <= y for r, c in cells)


def transform(grid):
    bg, comps = _components(grid)
    out = [row[:] for row in grid]

    # A large L-shaped object marks a cavity. Of two identical small objects,
    # the copy outside the cavity takes the L's color; the copy in the cavity
    # remains as it is.
    frames = []
    for i, (color, cells) in enumerate(comps):
        box = _corner_l(cells)
        if box is not None:
            frames.append((len(cells), i, color, cells, box))
    if not frames:
        return out
    _, frame_i, frame_color, frame_cells, box = max(frames)

    groups = {}
    for i, (color, cells) in enumerate(comps):
        if i == frame_i:
            continue
        groups.setdefault(_canonical(cells), []).append((i, color, cells))

    for group in groups.values():
        inside = [item for item in group if _inside_cavity(item[2], box)]
        outside = [item for item in group if not _inside_cavity(item[2], box)]
        if inside and outside:
            for i, color, cells in outside:
                for r, c in cells:
                    out[r][c] = frame_color
    return out


